Contents of file systemdna/web/lib/theme.ts:

1 | "use client";
2 | 
3 | import { useSyncExternalStore } from "react";
4 | 
5 | // Theme follows the HRMS rule: class "dark" on <html>, saved in localStorage.theme.
6 | 
7 | function subscribe(onChange: () => void) {
8 |   const observer = new MutationObserver(onChange);
9 |   observer.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
10 |   return () => observer.disconnect();
11 | }
12 | 
13 | export function useIsDark() {
14 |   return useSyncExternalStore(
15 |     subscribe,
16 |     () => document.documentElement.classList.contains("dark"),
17 |     () => false,
18 |   );
19 | }
20 | 
21 | export function setDarkMode(dark: boolean) {
22 |   document.documentElement.classList.toggle("dark", dark);
23 |   try {
24 |     localStorage.setItem("theme", dark ? "dark" : "light");
25 |   } catch {
26 |     // Storage can be blocked; the class change still applies.
27 |   }
28 | }
29 | 
30 | /** Runs before first paint (inlined in the root layout) to avoid a theme flash. */
31 | export const themeInitScript = `(function(){try{var t=localStorage.getItem('theme');var d=t?t==='dark':window.matchMedia('(prefers-color-scheme: dark)').matches;if(d)document.documentElement.classList.add('dark');}catch(e){}})();`;
