1 | "use client";
2 | 
3 | import { useMemo } from "react";
4 | import { create } from "zustand";
5 | import { createJSONStorage, persist } from "zustand/middleware";
6 | import { DATA_MODE, DEMO_REPOS, fetchGraph } from "@/lib/api";
7 | import type { Change, Graph, RunEvent } from "@/lib/types";
8 | 
9 | interface AppState {
10 |   graph: Graph | null;
11 |   graphError: string | null;
12 |   changes: Change[];
13 |   hydrated: boolean;
14 |   /** Demo repo id (demo mode only). */
15 |   repoId: string;
16 |   setRepo: (id: string) => Promise<void>;
17 |   loadGraph: () => Promise<void>;
18 |   addChange: (change: Change) => void;
19 |   appendEvent: (ev: RunEvent) => void;
20 |   resetEvents: (changeId: string) => void;
21 |   resetDemo: () => void;
22 |   nextChangeId: () => string;
23 | }
24 | 
25 | export const useApp = create<AppState>()(
26 |   persist(
27 |     (set, get) => ({
28 |       graph: null,
29 |       graphError: null,
30 |       changes: [],
31 |       hydrated: false,
32 |       repoId: DEMO_REPOS[0].id,
33 |       setRepo: async (id) => {
34 |         set({ repoId: id, graph: null });
35 |         await get().loadGraph();
36 |       },
37 |       loadGraph: async () => {
38 |         if (get().graph) return;
39 |         try {
40 |           set({ graph: await fetchGraph(get().repoId), graphError: null });
41 |         } catch (err) {
42 |           set({ graphError: err instanceof Error ? err.message : "Could not load the graph" });
43 |         }
44 |       },
45 |       addChange: (change) => set((s) => ({ changes: [change, ...s.changes] })),
46 |       appendEvent: (ev) =>
47 |         set((s) => ({
48 |           changes: s.changes.map((c) =>
49 |             c.id === ev.change_id ? { ...c, events: [...c.events, ev] } : c,
50 |           ),
51 |         })),
52 |       resetEvents: (changeId) =>
53 |         set((s) => ({
54 |           changes: s.changes.map((c) => (c.id === changeId ? { ...c, events: [] } : c)),
55 |         })),
56 |       resetDemo: () => set({ changes: [] }),
57 |       nextChangeId: () => {
58 |         const max = get().changes.reduce((m, c) => {
59 |           const n = Number(c.id.replace(/\D/g, ""));
60 |           return Number.isFinite(n) ? Math.max(m, n) : m;
61 |         }, 0);
62 |         return `chg-${String(max + 1).padStart(3, "0")}`;
63 |       },
64 |     }),
65 |     {
66 |       name: `systemdna-${DATA_MODE}`,
67 |       storage: createJSONStorage(() => localStorage),
68 |       partialize: (s) => ({ changes: s.changes, repoId: s.repoId }),
69 |       skipHydration: true,
70 |       onRehydrateStorage: () => () => useApp.setState({ hydrated: true }),
71 |     },
72 |   ),
73 | );
74 | 
75 | /** Changes that belong to the repo on screen. Older saved changes had no repo: they are ShopFlow's. */
76 | export function useRepoChanges(): Change[] {
77 |   const changes = useApp((s) => s.changes);
78 |   const repo = useApp((s) => s.graph?.repo);
79 |   return useMemo(
80 |     () => (repo ? changes.filter((c) => (c.repo ?? "samples/shopflow") === repo) : []),
81 |     [changes, repo],
82 |   );
83 | }
84 | 
85 | export function useChange(id: string | undefined) {
86 |   return useApp((s) => s.changes.find((c) => c.id === id));
87 | }
