1 | "use client";
2 | 
3 | import { useEffect, useMemo, useRef } from "react";
4 | import * as THREE from "three";
5 | import { OrbitControls } from "three/addons/controls/OrbitControls.js";
6 | import { CSS2DObject, CSS2DRenderer } from "three/addons/renderers/CSS2DRenderer.js";
7 | import { Maximize2, Minus, Plus, RotateCcw, RotateCw } from "lucide-react";
8 | import { cn } from "@/lib/cn";
9 | import { FOOTPRINT, layoutCity, type CityData } from "@/lib/city";
10 | import { useIsDark } from "@/lib/theme";
11 | import { readTokens, type Tokens } from "@/lib/tokens";
12 | 
13 | export type CityColorMode = "zinc" | "folder";
14 | 
15 | interface City3DProps {
16 |   data: CityData;
17 |   selected?: string | null;
18 |   onSelect?: (path: string | null) => void;
19 |   /** Dim every folder except this one. */
20 |   focusDir?: string | null;
21 |   colorMode?: CityColorMode;
22 |   className?: string;
23 | }
24 | 
25 | // Zinc shades per folder (default, follows the design system: no rainbow).
26 | const ZINC_LIGHT = ["#3F3F46", "#71717A", "#52525B", "#A1A1AA", "#27272A", "#8A8A93", "#63636B"];
27 | const ZINC_DARK = ["#E4E4E7", "#A1A1AA", "#D4D4D8", "#71717A", "#F4F4F5", "#B4B4BB", "#8A8A93"];
28 | // Opt-in folder colours, muted.
29 | const FOLDER = ["#5B8DEF", "#4FBFA5", "#D9648F", "#D9A441", "#9A7BE0", "#4BA3C7", "#C98A5A", "#7C9A5E"];
30 | 
31 | export function districtColor(index: number, mode: CityColorMode, dark: boolean) {
32 |   const list = mode === "folder" ? FOLDER : dark ? ZINC_DARK : ZINC_LIGHT;
33 |   return list[index % list.length];
34 | }
35 | 
36 | const ELEVATION = Math.atan(1 / Math.SQRT2); // true isometric: about 35 degrees
37 | 
38 | interface Built {
39 |   mesh: THREE.Mesh;
40 |   mat: THREE.MeshLambertMaterial;
41 |   edges: THREE.LineSegments;
42 |   cap?: THREE.Mesh;
43 |   label: CSS2DObject;
44 |   dir: string;
45 | }
46 | 
47 | export function City3D({ data, selected, onSelect, focusDir, colorMode = "zinc", className }: City3DProps) {
48 |   const hostRef = useRef<HTMLDivElement>(null);
49 |   const isDark = useIsDark();
50 |   const layout = useMemo(() => layoutCity(data), [data]);
51 |   const onSelectRef = useRef(onSelect);
52 |   const api = useRef<{
53 |     fit: () => void;
54 |     rotate: (deg: number) => void;
55 |     zoom: (f: number) => void;
56 |     apply: () => void;
57 |   } | null>(null);
58 |   const viewRef = useRef({ selected: selected ?? null, focusDir: focusDir ?? null, hovered: null as string | null });
59 | 
60 |   useEffect(() => {
61 |     onSelectRef.current = onSelect;
62 |   }, [onSelect]);
63 | 
64 |   // Build the whole scene. Rebuilt when the data, theme or colour mode changes.
65 |   useEffect(() => {
66 |     const host = hostRef.current;
67 |     if (!host) return;
68 |     const t: Tokens = readTokens();
69 |     const width = () => Math.max(1, host.clientWidth);
70 |     const height = () => Math.max(1, host.clientHeight);
71 | 
72 |     const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
73 |     renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
74 |     renderer.setSize(width(), height());
75 |     host.appendChild(renderer.domElement);
76 | 
77 |     const labels = new CSS2DRenderer();
78 |     labels.setSize(width(), height());
79 |     labels.domElement.style.position = "absolute";
80 |     labels.domElement.style.inset = "0";
81 |     labels.domElement.style.pointerEvents = "none";
82 |     host.appendChild(labels.domElement);
83 | 
84 |     const scene = new THREE.Scene();
85 |     const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, -1000, 2000);
86 |     const controls = new OrbitControls(camera, renderer.domElement);
87 |     controls.enableDamping = true;
88 |     controls.dampingFactor = 0.12;
89 |     controls.screenSpacePanning = false;
90 |     controls.mouseButtons = { LEFT: THREE.MOUSE.PAN, MIDDLE: THREE.MOUSE.DOLLY, RIGHT: THREE.MOUSE.ROTATE };
91 |     controls.touches = { ONE: THREE.TOUCH.PAN, TWO: THREE.TOUCH.DOLLY_ROTATE };
92 |     controls.minZoom = 0.35;
93 |     controls.maxZoom = 8;
94 |     controls.minPolarAngle = 0.35;
95 |     controls.maxPolarAngle = 1.3;
96 | 
97 |     // Light: soft sky light plus one sun, so each side of a building has its own shade.
98 |     scene.add(new THREE.HemisphereLight(0xffffff, isDark ? 0x202024 : 0xd4d4d8, isDark ? 1.35 : 1.6));
99 |     const sun = new THREE.DirectionalLight(0xffffff, isDark ? 1.2 : 1.1);
100 |     sun.position.set(-40, 90, 60);
101 |     scene.add(sun);
102 | 
103 |     // Ground grid.
104 |     const span = Math.max(layout.size.w, layout.size.d) * 3 + 60;
105 |     const grid = new THREE.GridHelper(span, Math.round(span / 8), t.border, t.border);
106 |     (grid.material as THREE.Material).transparent = true;
107 |     (grid.material as THREE.Material).opacity = isDark ? 0.55 : 0.7;
108 |     grid.position.y = -0.35;
109 |     scene.add(grid);
110 | 
111 |     const dirIndex = new Map(data.districts.map((d, i) => [d.dir, i]));
112 | 
113 |     // District plates and their labels.
114 |     for (const d of layout.districts) {
115 |       const color = new THREE.Color(districtColor(dirIndex.get(d.dir) ?? 0, colorMode, isDark));
116 |       const plateColor = new THREE.Color(t.surface).lerp(color, colorMode === "folder" ? 0.28 : 0.12);
117 |       const plate = new THREE.Mesh(
118 |         new THREE.BoxGeometry(d.w, 0.5, d.d),
119 |         new THREE.MeshLambertMaterial({ color: plateColor }),
120 |       );
121 |       plate.position.set(d.x + d.w / 2, -0.25, d.z + d.d / 2);
122 |       scene.add(plate);
123 |       const outline = new THREE.LineSegments(
124 |         new THREE.EdgesGeometry(plate.geometry),
125 |         new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.35 }),
126 |       );
127 |       outline.position.copy(plate.position);
128 |       scene.add(outline);
129 | 
130 |       const count = data.districts.find((x) => x.dir === d.dir)?.files.length ?? 0;
131 |       const el = document.createElement("div");
132 |       el.className = "flex flex-col items-center leading-tight select-none";
133 |       const name = document.createElement("span");
134 |       name.className = "type-label";
135 |       name.textContent = d.dir;
136 |       const sub = document.createElement("span");
137 |       sub.className = "type-caption";
138 |       sub.textContent = `${count} ${count === 1 ? "file" : "files"}`;
139 |       el.append(name, sub);
140 |       const label = new CSS2DObject(el);
141 |       label.position.set(d.x + d.w / 2, 0, d.z + d.d + 2.6);
142 |       scene.add(label);
143 |     }
144 | 
145 |     // Buildings: one per file.
146 |     const built = new Map<string, Built>();
147 |     const pickable: THREE.Mesh[] = [];
148 |     // Core modules get the inverse of the text colour so the cap stands out on zinc buildings.
149 |     const capColor = { entry: t.info, core: t.textInverse, hotspot: t.warning };
150 |     for (const f of data.files) {
151 |       const pos = layout.positions.get(f.path);
152 |       if (!pos) continue;
153 |       const color = districtColor(dirIndex.get(f.dir) ?? 0, colorMode, isDark);
154 |       const geo = new THREE.BoxGeometry(FOOTPRINT, pos.h, FOOTPRINT);
155 |       geo.translate(0, pos.h / 2, 0);
156 |       const mat = new THREE.MeshLambertMaterial({ color, emissive: new THREE.Color(0x000000) });
157 |       const mesh = new THREE.Mesh(geo, mat);
158 |       mesh.position.set(pos.x, 0, pos.z);
159 |       mesh.userData.path = f.path;
160 |       scene.add(mesh);
161 |       pickable.push(mesh);
162 | 
163 |       const edges = new THREE.LineSegments(
164 |         new THREE.EdgesGeometry(geo),
165 |         new THREE.LineBasicMaterial({ color: isDark ? "#000000" : "#FFFFFF", transparent: true, opacity: isDark ? 0.25 : 0.45 }),
166 |       );
167 |       edges.position.copy(mesh.position);
168 |       scene.add(edges);
169 | 
170 |       let cap: THREE.Mesh | undefined;
171 |       if (f.landmark) {
172 |         cap = new THREE.Mesh(
173 |           new THREE.BoxGeometry(FOOTPRINT + 0.06, 0.45, FOOTPRINT + 0.06),
174 |           new THREE.MeshLambertMaterial({ color: capColor[f.landmark], emissive: new THREE.Color(capColor[f.landmark]), emissiveIntensity: 0.25 }),
175 |         );
176 |         cap.position.set(pos.x, pos.h + 0.22, pos.z);
177 |         scene.add(cap);
178 |       }
179 | 
180 |       const wrap = document.createElement("div");
181 |       const tag = document.createElement("div");
182 |       tag.className =
183 |         "mb-1.5 px-1.5 py-0.5 rounded-md bg-surface/90 border border-border text-caption font-semibold text-text-primary shadow-2xs whitespace-nowrap select-none";
184 |       tag.textContent = f.path.split("/").pop() ?? f.path;
185 |       wrap.appendChild(tag);
186 |       const label = new CSS2DObject(wrap);
187 |       label.center.set(0.5, 1);
188 |       label.position.set(pos.x, pos.h + (cap ? 0.6 : 0.2), pos.z);
189 |       scene.add(label);
190 | 
191 |       built.set(f.path, { mesh, mat, edges, cap, label, dir: f.dir });
192 |     }
193 | 
194 |     // Import arcs.
195 |     const arcs: { line: THREE.Line; mat: THREE.LineBasicMaterial; from: string; to: string }[] = [];
196 |     for (const l of data.links) {
197 |       const a = layout.positions.get(l.from);
198 |       const b = layout.positions.get(l.to);
199 |       if (!a || !b) continue;
200 |       const start = new THREE.Vector3(a.x, a.h, a.z);
201 |       const end = new THREE.Vector3(b.x, b.h, b.z);
202 |       const dist = start.distanceTo(end);
203 |       const mid = start.clone().lerp(end, 0.5);
204 |       mid.y = Math.max(a.h, b.h) + 2 + dist * 0.35;
205 |       const curve = new THREE.QuadraticBezierCurve3(start, mid, end);
206 |       const mat = new THREE.LineBasicMaterial({ color: t.textTertiary, transparent: true, opacity: 0.18 });
207 |       const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(curve.getPoints(28)), mat);
208 |       scene.add(line);
209 |       arcs.push({ line, mat, from: l.from, to: l.to });
210 |     }
211 | 
212 |     // Camera: fit the city in view from a fixed isometric angle.
213 |     const maxH = Math.max(4, ...[...layout.positions.values()].map((p) => p.h));
214 |     let viewSize = 10;
215 |     const setFrustum = () => {
216 |       const aspect = width() / height();
217 |       camera.left = (-viewSize * aspect) / 2;
218 |       camera.right = (viewSize * aspect) / 2;
219 |       camera.top = viewSize / 2;
220 |       camera.bottom = -viewSize / 2;
221 |       camera.updateProjectionMatrix();
222 |     };
223 |     const fit = () => {
224 |       const aspect = width() / height();
225 |       // Screen width of an isometric box is about 0.71 x (w + d); its height adds the tallest building.
226 |       const across = (layout.size.w + layout.size.d) * 0.71 + 10;
227 |       const tall = (layout.size.w + layout.size.d) * 0.41 + maxH * 0.82 + 10;
228 |       viewSize = Math.max(across / aspect, tall);
229 |       controls.target.set(0, maxH * 0.3, 0);
230 |       const dist = 400;
231 |       camera.position.set(
232 |         dist * Math.cos(ELEVATION) * Math.sin(Math.PI / 4),
233 |         dist * Math.sin(ELEVATION),
234 |         dist * Math.cos(ELEVATION) * Math.cos(Math.PI / 4),
235 |       ).add(controls.target);
236 |       camera.zoom = 1;
237 |       setFrustum();
238 |       controls.update();
239 |     };
240 |     fit();
241 | 
242 |     // Smooth rotation around the vertical axis.
243 |     let pendingTurn = 0;
244 |     const rotate = (deg: number) => {
245 |       pendingTurn += (deg * Math.PI) / 180;
246 |     };
247 |     const zoom = (factor: number) => {
248 |       camera.zoom = THREE.MathUtils.clamp(camera.zoom * factor, controls.minZoom, controls.maxZoom);
249 |       camera.updateProjectionMatrix();
250 |     };
251 | 
252 |     // Selection, hover and folder focus.
253 |     const apply = () => {
254 |       const { selected: sel, focusDir: fd, hovered } = viewRef.current;
255 |       const file = sel ? data.files.find((f) => f.path === sel) : undefined;
256 |       const related = new Set<string>(file ? [file.path, ...file.imports, ...file.importedBy] : []);
257 |       for (const [path, b] of built) {
258 |         const dim = (file && !related.has(path)) || (fd && b.dir !== fd);
259 |         // Switching transparency changes the shader, so three.js must recompile it.
260 |         if (b.mat.transparent !== Boolean(dim)) b.mat.needsUpdate = true;
261 |         b.mat.transparent = Boolean(dim);
262 |         b.mat.opacity = dim ? 0.16 : 1;
263 |         b.mat.depthWrite = !dim;
264 |         (b.edges.material as THREE.LineBasicMaterial).opacity = dim ? 0.04 : isDark ? 0.25 : 0.45;
265 |         if (b.cap) {
266 |           const cm = b.cap.material as THREE.MeshLambertMaterial;
267 |           if (cm.transparent !== Boolean(dim)) cm.needsUpdate = true;
268 |           cm.transparent = Boolean(dim);
269 |           cm.opacity = dim ? 0.2 : 1;
270 |         }
271 |         b.mat.emissive.set(path === sel ? (isDark ? "#3F3F46" : "#52525B") : path === hovered ? (isDark ? "#27272A" : "#27272A") : "#000000");
272 |         b.mat.emissiveIntensity = path === sel ? 0.9 : 0.5;
273 |         const landmark = data.files.find((f) => f.path === path)?.landmark;
274 |         const show = path === sel || path === hovered || (!file && !fd && Boolean(landmark)) || (file && related.has(path) && path !== sel && related.size <= 8);
275 |         // CSS2DRenderer owns element.style.display, so toggle the object instead.
276 |         b.label.visible = Boolean(show);
277 |       }
278 |       for (const a of arcs) {
279 |         const touches = file && (a.from === file.path || a.to === file.path);
280 |         const inDir = !fd || built.get(a.from)?.dir === fd || built.get(a.to)?.dir === fd;
281 |         a.line.visible = file ? Boolean(touches) : inDir;
282 |         a.mat.color.set(touches ? t.textPrimary : t.textTertiary);
283 |         a.mat.opacity = touches ? 0.95 : fd ? 0.35 : 0.18;
284 |       }
285 |     };
286 |     apply();
287 |     api.current = { fit, rotate, zoom, apply };
288 | 
289 |     // Picking.
290 |     const ray = new THREE.Raycaster();
291 |     const pointer = new THREE.Vector2();
292 |     const pick = (ev: PointerEvent): string | null => {
293 |       const r = renderer.domElement.getBoundingClientRect();
294 |       pointer.set(((ev.clientX - r.left) / r.width) * 2 - 1, -((ev.clientY - r.top) / r.height) * 2 + 1);
295 |       ray.setFromCamera(pointer, camera);
296 |       const hit = ray.intersectObjects(pickable, false)[0];
297 |       return (hit?.object.userData.path as string | undefined) ?? null;
298 |     };
299 |     let down: { x: number; y: number } | null = null;
300 |     const onDown = (e: PointerEvent) => {
301 |       down = { x: e.clientX, y: e.clientY };
302 |     };
303 |     const onUp = (e: PointerEvent) => {
304 |       if (down && Math.hypot(e.clientX - down.x, e.clientY - down.y) < 5) onSelectRef.current?.(pick(e));
305 |       down = null;
306 |     };
307 |     let hoverQueued = false;
308 |     const onMove = (e: PointerEvent) => {
309 |       if (hoverQueued || e.buttons) return;
310 |       hoverQueued = true;
311 |       requestAnimationFrame(() => {
312 |         hoverQueued = false;
313 |         const p = pick(e);
314 |         renderer.domElement.style.cursor = p ? "pointer" : "grab";
315 |         if (p !== viewRef.current.hovered) {
316 |           viewRef.current.hovered = p;
317 |           apply();
318 |         }
319 |       });
320 |     };
321 |     renderer.domElement.addEventListener("pointerdown", onDown);
322 |     renderer.domElement.addEventListener("pointerup", onUp);
323 |     renderer.domElement.addEventListener("pointermove", onMove);
324 | 
325 |     const onKey = (e: KeyboardEvent) => {
326 |       const tag = (e.target as HTMLElement)?.tagName;
327 |       if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return;
328 |       if (e.key === "[") rotate(-45);
329 |       if (e.key === "]") rotate(45);
330 |       if (e.key === "0") fit();
331 |     };
332 |     window.addEventListener("keydown", onKey);
333 | 
334 |     const ro = new ResizeObserver(() => {
335 |       renderer.setSize(width(), height());
336 |       labels.setSize(width(), height());
337 |       setFrustum();
338 |     });
339 |     ro.observe(host);
340 | 
341 |     let frame = 0;
342 |     const up = new THREE.Vector3(0, 1, 0);
343 |     const tick = () => {
344 |       if (Math.abs(pendingTurn) > 0.0005) {
345 |         const step = pendingTurn * 0.14;
346 |         pendingTurn -= step;
