/**
 * Landing page data contract tests.
 * These run purely on the TypeScript modules — no DOM needed.
 */
import { describe, it, expect } from "vitest";
import { metrics } from "../landing/metrics";
import { siteConfig } from "../landing/siteConfig";

describe("metrics.ts", () => {
  it("exports an array of metrics", () => {
    expect(Array.isArray(metrics)).toBe(true);
    expect(metrics.length).toBeGreaterThan(0);
  });

  it("every metric has a label and description", () => {
    for (const m of metrics) {
      expect(typeof m.label).toBe("string");
      expect(m.label.length).toBeGreaterThan(0);
      expect(typeof m.description).toBe("string");
    }
  });

  it("all metric values are null (not yet measured)", () => {
    for (const m of metrics) {
      expect(m.value).toBeNull();
    }
  });

  it("null values should render as 'Measured live in the demo'", () => {
    for (const m of metrics) {
      // The render contract: null → placeholder text
      const display = m.value === null ? "Measured live in the demo" : String(m.value);
      expect(display).toBe("Measured live in the demo");
    }
  });

  it("every metric is labelled Target (not as an achieved result)", () => {
    // All values are null — the UI renders them with a Target badge
    // This test confirms the data contract: no metric has a non-null value
    const measured = metrics.filter((m) => m.value !== null);
    expect(measured).toHaveLength(0);
  });
});

