/**
 * Landing page component render tests.
 * Uses @testing-library/react + happy-dom.
 *
 * We test the assembled LandingPage for:
 *  - single h1 with "SystemDNA"
 *  - tagline text
 *  - "Enter Agent City" link → /city
 *  - "Watch the replay" link → /city?mode=replay
 *  - ProofSection metric tiles: Target badge + "Measured live in the demo"
 */
import { describe, it, expect, vi, beforeAll } from "vitest";
import { render, screen } from "@testing-library/react";
import React from "react";

// --- Next.js shims -----------------------------------------------------------
// next/link renders a plain <a> in test environment
vi.mock("next/link", () => ({
  default: ({ href, children, ...props }: { href: string; children: React.ReactNode; [key: string]: unknown }) =>
    React.createElement("a", { href, ...props }, children),
}));

// next/navigation is not used in landing components but imported transitively
vi.mock("next/navigation", () => ({
  useRouter: () => ({ push: vi.fn(), replace: vi.fn() }),
  usePathname: () => "/",
  useSearchParams: () => new URLSearchParams(),
  redirect: vi.fn(),
}));

// next/font/google — return dummy variable names
vi.mock("next/font/google", () => ({
  Geist: () => ({ variable: "--font-geist-sans", className: "" }),
  Geist_Mono: () => ({ variable: "--font-geist-mono", className: "" }),
  Space_Grotesk: () => ({ variable: "--font-space-grotesk", className: "" }),
  JetBrains_Mono: () => ({ variable: "--font-jetbrains-mono", className: "" }),
}));

// ResizeObserver is not in happy-dom
beforeAll(() => {
  if (!("ResizeObserver" in globalThis)) {
    globalThis.ResizeObserver = class {
      observe() {}
      unobserve() {}
      disconnect() {}
    };
  }
  // matchMedia shim
  if (!window.matchMedia) {
    Object.defineProperty(window, "matchMedia", {
      writable: true,
      value: (query: string) => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      }),
    });
  }
  // WebGL not available in test env
  HTMLCanvasElement.prototype.getContext = vi.fn(() => null);
});

// ---------------------------------------------------------------------------

import { LandingPage } from "@/app/landing/LandingPage";

describe("LandingPage", () => {
  it("renders a single h1 containing 'SystemDNA'", () => {
    render(React.createElement(LandingPage));
    const headings = screen.getAllByRole("heading", { level: 1 });
    expect(headings).toHaveLength(1);
    expect(headings[0].textContent).toMatch(/SystemDNA/i);
  });

  it("renders the tagline", () => {
    render(React.createElement(LandingPage));
    expect(
      screen.getByText(/Find References for your whole system, and fix them all/i),
    ).toBeInTheDocument();
  });

  it('"Enter Agent City" button links to /city', () => {
    render(React.createElement(LandingPage));
    const link = screen.getByRole("link", { name: /Enter Agent City/i });
    expect(link).toHaveAttribute("href", "/city");
  });

  it('"Watch the replay" button links to /city?mode=replay', () => {
    render(React.createElement(LandingPage));
    const link = screen.getByRole("link", { name: /Watch the replay/i });
    expect(link).toHaveAttribute("href", "/city?mode=replay");
  });
});

describe("ProofSection metric tiles", () => {
  it("every tile shows a 'Target' badge", () => {
    render(React.createElement(LandingPage));
    const badges = screen.getAllByText("Target");
    expect(badges.length).toBeGreaterThan(0);
  });

  it("every tile shows 'Measured live in the demo' when the value is null", () => {
    render(React.createElement(LandingPage));
    const placeholders = screen.getAllByText(/Measured live in the demo/i);
    // All metrics have null values, so every tile shows this placeholder
    expect(placeholders.length).toBeGreaterThan(0);
  });
});

