  background-color: rgba(255, 255, 255, 0.02) !important;
}

/* Wildcard subtle hovers for all table rows in dark mode */
.dark tr[class*="hover:bg-zinc-"]:hover {
  background-color: rgba(255, 255, 255, 0.03) !important;
}

/* Nested element overrides to create visual hierarchy */
.dark .bg-surface .bg-surface {
  background-color: #1E1E20 !important;
  border-color: #3F3F46 !important;
}
.dark .bg-surface .border-border {
  border-color: #2D2D30 !important;
}
.dark .bg-surface .bg-surface .border-border {
  border-color: #3F3F46 !important;
}

/* Ensure table cells have lighter backgrounds and borders */
.dark table {
  background-color: #1E1E20 !important;
  border-color: #3F3F46 !important;
}
.dark th {
  background-color: #161618 !important;
  border-color: #2D2D30 !important;
}
.dark td {
  border-color: #2D2D30 !important;
}

/* SVG Stroke and Fill overrides for dark mode charts */
.dark svg [stroke="#F4F4F5"] {
  stroke: var(--border) !important;
}
.dark svg [stroke="#E4E4E7"] {
  stroke: var(--border-strong) !important;
}
.dark svg [stroke="#18181B"] {
  stroke: var(--text-primary) !important;
}
.dark svg [stroke="var(--divider)"] {
  stroke: var(--divider) !important;
}
.dark svg [stroke="var(--border)"] {
  stroke: var(--border) !important;
}

/* Recharts bar/pie fills that were baked as near-black — lift them in dark mode */
.dark .recharts-wrapper svg [fill="#18181B"],
.dark .recharts-wrapper svg [fill="#09090B"],
.dark .recharts-wrapper svg [fill="#27272A"] {
  fill: #E4E4E7 !important;
}
.dark .recharts-wrapper svg [fill="#3F3F46"] {
  fill: #D4D4D8 !important;
}
.dark .recharts-wrapper svg [fill="#52525B"] {
  fill: #A1A1AA !important;
}
.dark .recharts-wrapper svg stop[stop-color="#18181B"] {
  stop-color: var(--chart-bar-to) !important;
}
.dark .recharts-wrapper svg stop[stop-color="#E4E4E7"] {
  stop-color: var(--chart-bar-from) !important;
}

/* Ensure Recharts grid lines and tooltips adapt to dark mode */
.dark .recharts-cartesian-grid-horizontal line,
.dark .recharts-cartesian-grid-vertical line {
  stroke: var(--divider) !important;
}
.dark .recharts-default-tooltip {
  background-color: var(--surface-secondary) !important;
  border-color: var(--border-strong) !important;
}


/* Ensure all hardcoded Tailwind badge and status classes automatically adapt inside dark mode */

/* Success Badges (Emerald) */
.dark .bg-emerald-50,
.dark .bg-emerald-100,
.dark .hover\:bg-emerald-50:hover {
  background-color: var(--success-soft) !important;
}
.dark .text-emerald-700,
.dark .text-emerald-600 {
  color: var(--success) !important;
}
.dark .border-emerald-200\/50,
.dark .border-emerald-200,
.dark .border-emerald-100 {
  border-color: rgba(74, 222, 128, 0.2) !important;
}

/* Info Badges (Sky/Blue/Indigo) */
.dark .bg-sky-50,
.dark .bg-sky-100,
.dark .bg-blue-50,
.dark .bg-indigo-50,
.dark .hover\:bg-sky-50:hover,
.dark .hover\:bg-blue-50:hover {
  background-color: var(--info-soft) !important;
}
.dark .text-sky-700,
.dark .text-sky-600,
.dark .text-blue-700,
.dark .text-blue-600,
.dark .text-indigo-700 {
  color: var(--info) !important;
}
.dark .border-sky-200\/50,
.dark .border-sky-200,
.dark .border-blue-200\/50,
.dark .border-blue-200,
.dark .border-indigo-200\/50 {
  border-color: rgba(56, 189, 248, 0.2) !important;
}

/* Warning Badges (Amber/Yellow) */
.dark .bg-amber-50,
.dark .bg-amber-100,
.dark .bg-yellow-50,
.dark .hover\:bg-amber-50:hover {
  background-color: var(--warning-soft) !important;
}
.dark .text-amber-700,
.dark .text-amber-600,
.dark .text-yellow-700 {
  color: var(--warning) !important;
}
.dark .border-amber-200\/50,
.dark .border-amber-200,
.dark .border-yellow-200\/50 {
  border-color: rgba(251, 191, 36, 0.2) !important;
}

/* Error/Destructive Badges (Red/Rose) */
.dark .bg-red-50,
.dark .bg-red-100,
.dark .bg-rose-50,
.dark .bg-rose-100,
.dark .hover\:bg-red-50:hover,
.dark .hover\:bg-rose-50:hover {
  background-color: var(--error-soft) !important;
}
.dark .text-red-700,
.dark .text-red-600,
.dark .text-rose-700,
.dark .text-rose-600 {
  color: var(--error) !important;
}
.dark .border-red-200\/50,
.dark .border-red-200,
.dark .border-rose-200\/50,
.dark .border-rose-200 {
  border-color: rgba(248, 113, 113, 0.2) !important;
}



@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground text-body font-normal;
  }
  html {
    @apply font-sans;
  }
}

/*
 * Locked type roles — prefer these over ad-hoc text-* + font-* combos in app UI.
 * Landing/auth pages should not use these; they keep their own scale.
 */
@layer components {
  .type-title {
    font-size: var(--text-title);
    line-height: var(--text-title--line-height);
    letter-spacing: var(--text-title--letter-spacing);
    font-weight: 500;
    color: var(--text-primary);
  }

  .type-subtitle {
    font-size: var(--text-body);
    line-height: var(--text-body--line-height);
    letter-spacing: var(--text-body--letter-spacing);
    font-weight: 500;
    color: var(--text-secondary);
  }

  .type-heading {
    font-size: var(--text-heading);
    line-height: var(--text-heading--line-height);
    letter-spacing: var(--text-heading--letter-spacing);
    font-weight: 600;
    color: var(--text-primary);
  }

  .type-body {
    font-size: var(--text-body);
    line-height: var(--text-body--line-height);
    letter-spacing: var(--text-body--letter-spacing);
    font-weight: 400;
    color: var(--text-primary);
  }

  .type-caption {
    font-size: var(--text-caption);
    line-height: var(--text-caption--line-height);
    letter-spacing: var(--text-caption--letter-spacing);
    font-weight: 500;
    color: var(--text-tertiary);
  }

  .type-metric {
    font-size: var(--text-metric);
    line-height: var(--text-metric--line-height);
    letter-spacing: var(--text-metric--letter-spacing);
    font-weight: 600;
    color: var(--text-primary);
  }

  .type-label {
    font-size: var(--text-caption);
    line-height: var(--text-caption--line-height);
    letter-spacing: 0.02em;
    font-weight: 600;
    text-transform: uppercase;
    color: var(--text-secondary);
  }
}

/* ------------------------------------------------------------------
 * SystemDNA additions. Keep to the HRMS language: zinc first,
 * status colour only for state.
 * ------------------------------------------------------------------ */

/* Cytoscape canvas container for the Agent City map */
.city-canvas {
  background-color: var(--background);
  background-image: radial-gradient(var(--divider) 1px, transparent 1px);
  background-size: 20px 20px;
}

/* Thin scrollbars inside dense panels */
.scroll-thin {
  scrollbar-width: thin;
  scrollbar-color: var(--border-strong) transparent;
}

